<?php require __DIR__.'/config.php';$u=require_login();$b=require_business();if(!can('qr')){http_response_code(403);exit('Forbidden');}$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$type=$_POST['type']??'table';if($b['type']==='hotel'&&!in_array($type,['room','table','service'],true))$type='service';if($b['type']==='restaurant'&&!in_array($type,['table','service'],true))$type='table';$name=trim($_POST['name']);$out=(int)$_POST['outlet_id']?:null;if(!$name)throw new RuntimeException('Name is required.');$s=$pdo->prepare("INSERT INTO locations(business_id,type,name,outlet_id,created_at) VALUES(?,?,?,?,NOW())");$s->execute([$b['id'],$type,$name,$out]);$lid=$pdo->lastInsertId();$token=random_token();$s=$pdo->prepare("INSERT INTO qr_codes(business_id,location_id,outlet_id,token,label,created_at) VALUES(?,?,?,?,?,NOW())");$s->execute([$b['id'],$lid,$out,$token,$name]);flash('QR created.');}catch(Throwable $e){flash($e->getMessage(),'error');}redirect('qr.php');}$out=$pdo->prepare("SELECT * FROM outlets WHERE business_id=? AND status='active'");$out->execute([$b['id']]);$out=$out->fetchAll();$q=$pdo->prepare("SELECT q.*,l.type,l.name location_name,o.name outlet_name FROM qr_codes q LEFT JOIN locations l ON l.id=q.location_id LEFT JOIN outlets o ON o.id=q.outlet_id WHERE q.business_id=? ORDER BY q.id DESC");$q->execute([$b['id']]);$q=$q->fetchAll();include __DIR__.'/app/layout_top.php';?><div class="page-head"><div><div class="eyebrow">Guest access</div><h1>QR codes</h1><p>Each QR carries its table, room or service context.</p></div></div><div class="panel"><form method="post" class="form-grid"><?=csrf_field()?><label>Location type<select name="type"><?php if($b['type']==='hotel'):?><option value="room">Hotel room</option><?php endif;?><option value="table">Table</option><option value="service">Service / other</option></select></label><label>Name<input name="name" placeholder="Table 7 / Room 305" required></label><label>Outlet<select name="outlet_id"><option value="">General</option><?php foreach($out as $o):?><option value="<?=$o['id']?>"><?=e($o['name'])?></option><?php endforeach;?></select></label><button class="btn gold">Generate QR</button></form></div><div class="panel"><h3>Generated</h3><?php foreach($q as $r):?><div class="row"><div><b><?=e($r['label'])?></b><div class="small muted"><?=e(strtoupper($r['type']))?> · <?=e($r['outlet_name']??'General')?> · <?=number_format((int)$r['scans'])?> scans</div></div><a class="btn" href="qr-card.php?id=<?=$r['id']?>">View / Print</a></div><?php endforeach;if(!$q):?><p class="muted">No QR codes yet.</p><?php endif;?></div><?php include __DIR__.'/app/layout_bottom.php';
